package dev.zomboid.turretpower;import java.util.*;public class Checks{public record P(int x,int y,int z){public P offset(int a,int b,int c){return new P(x+a,y+b,z+c);}}public static class S{public String id;public S(String id){this.id=id;}public String getBlock(){return id;}public boolean is(Object tag){return id.contains("glass");}}public static class W{public boolean client,loaded=true,bedWorks=true;public Map<P,S> blocks=new HashMap<>();public List<Object> players=new ArrayList<>();public boolean isClientSide(){return client;}public boolean hasChunkAt(P p){return loaded;}public S getBlockState(P p){return blocks.getOrDefault(p,new S("minecraft:air"));}public List<Object> players(){return players;}public W dimensionType(){return this;}public boolean bedWorks(){return bedWorks;}}}